mapper.update:
UPDATE SMT_AUTH_REQUEST_INTAKE SET AUTH_SCOPE=#{authScope},OUTCOME=#{outcome},CHILD_COUNT=#{childCount},CHILD_MANIFEST_HASH=#{childManifestHash},ACCEPTED_AT=#{acceptedAt,jdbcType=TIMESTAMP}
WHERE OPERATION_KEY=#{operationKey} AND ACTOR_ID=#{actorId} AND REQUEST_KEY=#{requestKey}
  AND REQUEST_KIND=#{requestKind} AND FINGERPRINT_VERSION=#{fingerprintVersion} AND REQUEST_FINGERPRINT=#{requestFingerprint}
  AND OUTCOME IS NULL AND AUTH_SCOPE IS NULL AND CHILD_COUNT IS NULL AND CHILD_MANIFEST_HASH IS NULL AND ACCEPTED_AT IS NULL
